def check_solutions():
    # The equation derived is: 98*b3 - 7*b2 - 4*b1 - 1*b0 = 0
    # Constraints:
    # 1 <= b3 <= 6
    # 0 <= b2, b1, b0 <= 6

    solutions = []

    for b3 in range(1, 7):
        for b2 in range(7):
            for b1 in range(7):
                for b0 in range(7):
                    LHS = 98 * b3 - 7 * b2 - 4 * b1 - b0
                    if LHS == 0:
                        solutions.append((b3, b2, b1, b0))

    return solutions

solutions = check_solutions()
print(f"Found {len(solutions)} solutions.")
print("Solutions (b3, b2, b1, b0):", solutions)
